-- Migration: Increase token column length for email_verification_tokens and password_reset_tokens
-- Date: 2025-10-24
-- Reason: tokens generated by secrets.token_urlsafe(32) are 43 characters, but columns were only 36 chars

-- Increase email_verification_tokens token column from CHAR(36) to VARCHAR(64)
ALTER TABLE email_verification_tokens 
MODIFY COLUMN token VARCHAR(64) NOT NULL;

-- Increase password_reset_tokens token column from CHAR(36) to VARCHAR(64)
ALTER TABLE password_reset_tokens 
MODIFY COLUMN token VARCHAR(64) NOT NULL;

